package com.bank.spark.model;

// Describes a workload so a storage format can be recommended.
public class Workload {
    private final String name;
    private final boolean writeHeavy;
    private final boolean schemaEvolves;
    private final boolean selectiveColumnReads;
    private final boolean needsAcidUpdates;
    private final boolean hiveEcosystem;

    public Workload(String name, boolean writeHeavy, boolean schemaEvolves,
                    boolean selectiveColumnReads, boolean needsAcidUpdates, boolean hiveEcosystem) {
        this.name = name;
        this.writeHeavy = writeHeavy;
        this.schemaEvolves = schemaEvolves;
        this.selectiveColumnReads = selectiveColumnReads;
        this.needsAcidUpdates = needsAcidUpdates;
        this.hiveEcosystem = hiveEcosystem;
    }

    public String getName() { return name; }
    public boolean isWriteHeavy() { return writeHeavy; }
    public boolean isSchemaEvolves() { return schemaEvolves; }
    public boolean isSelectiveColumnReads() { return selectiveColumnReads; }
    public boolean isNeedsAcidUpdates() { return needsAcidUpdates; }
    public boolean isHiveEcosystem() { return hiveEcosystem; }
}
