package com.bank.spark.service;

import com.bank.spark.model.Workload;
import java.util.logging.Logger;

// Recommends Avro, Parquet, or ORC based on workload traits.
public class FormatAdvisor {

    private static final Logger log = Logger.getLogger(FormatAdvisor.class.getName());

    public String recommend(Workload w) {
        // ACID updates in Hive → ORC.
        if (w.isNeedsAcidUpdates() && w.isHiveEcosystem()) {
            log.info(() -> w.getName() + ": ACID updates in Hive → ORC");
            return "ORC — columnar + built-in indexes + Hive ACID updates";
        }
        // Write-heavy / evolving schema → Avro.
        if (w.isWriteHeavy() || w.isSchemaEvolves()) {
            log.info(() -> w.getName() + ": write-heavy / schema evolves → Avro");
            return "AVRO — row-based, embedded schema, great for write + evolution";
        }
        // Read-heavy selective analytics → Parquet.
        if (w.isSelectiveColumnReads()) {
            log.info(() -> w.getName() + ": read-heavy selective columns → Parquet");
            return "PARQUET — columnar, column pruning + predicate pushdown";
        }
        log.info(() -> w.getName() + ": general analytics → Parquet (default)");
        return "PARQUET — default columnar analytical format";
    }
}
