package com.bank.spark;

import com.bank.spark.model.Workload;
import com.bank.spark.service.FormatAdvisor;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: recommend a storage format for each banking workload.
public class FormatAdvisorDemo {

    private static final Logger log = Logger.getLogger(FormatAdvisorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        FormatAdvisor advisor = new FormatAdvisor();

        List<Workload> workloads = List.of(
            new Workload("txn-ingestion", true, true, false, false, false),
            new Workload("reporting-scans", false, false, true, false, false),
            new Workload("hive-regulatory", false, false, true, true, true));

        for (Workload w : workloads) {
            String fmt = advisor.recommend(w);
            log.info(() -> "Workload " + w.getName() + " → " + fmt);
        }
        log.info("Format advisor demo complete.");
    }
}
